-- IMP-1030-FC-E（#896）：法人归属会签到期后的逐级提醒与升级通知（ADR-0073 第 3 条第 6 款；one-design 裁定 #896 第 3 项）。
-- 对象类别新增 ATTRIBUTION_COUNTERSIGN（对象 ID 为会签行 ID）；用途新增 COUNTERSIGN_OVERDUE_REMINDER、COUNTERSIGN_ESCALATED_TO_ADMINS、COUNTERSIGN_ESCALATED_FINAL。保留 main 上已有的全部取值。
ALTER TABLE platform_integration.outbound_deliveries DROP CONSTRAINT ck_outbound_deliveries_subject_kind;
ALTER TABLE platform_integration.outbound_deliveries ADD CONSTRAINT ck_outbound_deliveries_subject_kind CHECK (subject_kind IN ('APPROVAL_TASK', 'APPROVAL_INSTANCE', 'SEPARATION_HOLD', 'PERSONNEL_COMMAND', 'ACCOUNT_ROLE_GRANT', 'USER_ACCOUNT', 'PERMISSION_ADJUSTMENT', 'ATTRIBUTION_COUNTERSIGN'));
ALTER TABLE platform_integration.outbound_deliveries DROP CONSTRAINT ck_outbound_deliveries_purpose_kind;
ALTER TABLE platform_integration.outbound_deliveries ADD CONSTRAINT ck_outbound_deliveries_purpose_kind CHECK (purpose_kind IN ('TASK_ASSIGNED', 'TASK_TRANSFERRED', 'TASK_REASSIGNED', 'TASK_OVERDUE', 'TASK_ESCALATED', 'APPROVAL_COMPLETED', 'SEPARATION_HOLD_NOTICE', 'UNPAID_LEAVE_START_NOTICE', 'ROLE_REVOCATION_NOTICE', 'ACCOUNT_DISABLE_NOTICE', 'PERMISSION_ADJUSTMENT_ASSIGNED', 'COUNTERSIGN_OVERDUE_REMINDER', 'COUNTERSIGN_ESCALATED_TO_ADMINS', 'COUNTERSIGN_ESCALATED_FINAL'));
COMMENT ON COLUMN platform_integration.outbound_deliveries.subject_kind IS '对象类别 / 对象 ID：被记录或被投递的业务对象的类别与自有 ID。对象类别：APPROVAL_TASK 审批任务 / APPROVAL_INSTANCE 审批实例 / SEPARATION_HOLD 待放行离职 / PERSONNEL_COMMAND 人事命令 / ACCOUNT_ROLE_GRANT 角色授予 / USER_ACCOUNT 用户账号 / PERMISSION_ADJUSTMENT 待调整权限 / ATTRIBUTION_COUNTERSIGN 法人归属会签';
COMMENT ON COLUMN platform_integration.outbound_deliveries.purpose_kind IS '投递用途：一张卡为什么发。TASK_ASSIGNED 任务指派 / TASK_TRANSFERRED 任务转交 / TASK_REASSIGNED 任务改派 / TASK_OVERDUE 任务超时 / TASK_ESCALATED 任务升级 / APPROVAL_COMPLETED 审批完成 / SEPARATION_HOLD_NOTICE 放行后仅剩 1 名超管的通知 / UNPAID_LEAVE_START_NOTICE 停薪留职开始后仅剩 1 名超管的通知 / ROLE_REVOCATION_NOTICE 撤销管理员角色授予后仅剩 1 名超管的通知 / ACCOUNT_DISABLE_NOTICE 停用管理员账号后仅剩 1 名超管的通知 / PERMISSION_ADJUSTMENT_ASSIGNED 待调整权限已派给新部门负责人 / COUNTERSIGN_OVERDUE_REMINDER 会签逾期提醒（第 1 级）/ COUNTERSIGN_ESCALATED_TO_ADMINS 会签升级（第 2 级，送业务管理员）/ COUNTERSIGN_ESCALATED_FINAL 会签升级（第 3 级，再送法人财务负责人）';
